package com.github.auties00.daedalus.processor.model;

import javax.lang.model.element.TypeElement;
import java.util.Objects;
import java.util.Optional;

/**
 * A companion parameters annotation, which supplies the arguments of the additional
 * parameters of the converters declared by a type.
 *
 * <p>Companion parameters annotations come in two flavors:
 * <ul>
 * <li>{@link Concrete} annotations are backed by an existing {@link TypeElement}, either
 *     loaded from a dependency or generated by a previous processing round.
 * <li>{@link Synthetic} annotations are generated by the current processing round, so
 *     no {@link TypeElement} exists for them yet.
 * </ul>
 *
 * <p>Two instances are equal if they have the same {@linkplain #qualifiedName() qualified
 * name}, regardless of their flavor: a synthetic annotation required by a converter linked
 * in one round is equal to the concrete annotation applied to a use site that is processed
 * in a later round, once the annotation has been generated.
 *
 * <p>Instances are created via the {@link #of(TypeElement)} and {@link #of(String)}
 * factory methods. They are immutable and thread-safe.
 */
public sealed interface DaedalusConverterParametersElement {
    /**
     * Returns the type element backing this annotation, if one exists.
     *
     * @return an {@link Optional} containing the type element for concrete annotations,
     *         or an empty {@code Optional} for synthetic annotations
     */
    Optional<TypeElement> element();

    /**
     * Returns the fully qualified name of this annotation.
     *
     * @return the qualified name
     */
    String qualifiedName();

    /**
     * Creates a concrete annotation backed by an existing annotation type.
     *
     * @param element the annotation type
     * @return a new concrete annotation
     * @throws NullPointerException if {@code element} is {@code null}
     */
    static DaedalusConverterParametersElement of(TypeElement element) {
        return new Concrete(element);
    }

    /**
     * Creates a synthetic annotation that is generated by the current processing round.
     *
     * @param qualifiedName the fully qualified name of the annotation
     * @return a new synthetic annotation
     * @throws NullPointerException if {@code qualifiedName} is {@code null}
     */
    static DaedalusConverterParametersElement of(String qualifiedName) {
        return new Synthetic(qualifiedName);
    }

    /**
     * A companion parameters annotation backed by an existing {@link TypeElement}.
     */
    final class Concrete implements DaedalusConverterParametersElement {
        private final TypeElement element;
        private final String qualifiedName;

        private Concrete(TypeElement element) {
            this.element = Objects.requireNonNull(element, "element cannot be null");
            // Read once, so that the parallel path search never queries javac
            this.qualifiedName = element.getQualifiedName().toString();
        }

        /**
         * {@inheritDoc}
         */
        @Override
        public Optional<TypeElement> element() {
            return Optional.of(element);
        }

        /**
         * {@inheritDoc}
         */
        @Override
        public String qualifiedName() {
            return qualifiedName;
        }

        @Override
        public boolean equals(Object obj) {
            return obj instanceof DaedalusConverterParametersElement that
                    && qualifiedName.equals(that.qualifiedName());
        }

        @Override
        public int hashCode() {
            return qualifiedName.hashCode();
        }

        @Override
        public String toString() {
            return qualifiedName;
        }
    }

    /**
     * A companion parameters annotation that is generated by the current processing
     * round, and has no backing {@link TypeElement} yet.
     */
    final class Synthetic implements DaedalusConverterParametersElement {
        private final String qualifiedName;

        private Synthetic(String qualifiedName) {
            this.qualifiedName = Objects.requireNonNull(qualifiedName, "qualifiedName cannot be null");
        }

        /**
         * {@inheritDoc}
         */
        @Override
        public Optional<TypeElement> element() {
            return Optional.empty();
        }

        /**
         * {@inheritDoc}
         */
        @Override
        public String qualifiedName() {
            return qualifiedName;
        }

        @Override
        public boolean equals(Object obj) {
            return obj instanceof DaedalusConverterParametersElement that
                    && qualifiedName.equals(that.qualifiedName());
        }

        @Override
        public int hashCode() {
            return qualifiedName.hashCode();
        }

        @Override
        public String toString() {
            return qualifiedName;
        }
    }
}
